@typeparam TItem
@implements IAsyncDisposable
@inject IJSRuntime JS

<div class="infinite-scroll-container" style="overflow-y:auto; max-height:@Height">
    @foreach (var item in Items)
    {
        @ChildContent(item)
    }

    @if (HasMore)
    {
        <div @ref="_sentinelRef" class="infinite-scroll-sentinel">
            @if (_isLoading)
            {
                <div class="d-flex justify-content-center p-3">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
        </div>
    }
</div>

using Microsoft.AspNetCore.Components;
using Microsoft.JSInterop;

namespace sv_61710d93e4ca4d538110d85f23fa3ab2.Components;

public partial class InfiniteScrollList<TItem> : IAsyncDisposable
{
    private ElementReference _sentinelRef;
    private IJSObjectReference? _module;
    private IJSObjectReference? _observer;
    private DotNetObjectReference<InfiniteScrollList<TItem>>? _dotNetRef;
    private bool _isLoading;

    [Parameter, EditorRequired]
    public IReadOnlyList<TItem> Items { get; set; } = [];

    [Parameter, EditorRequired]
    public RenderFragment<TItem> ChildContent { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback OnLoadMore { get; set; }

    [Parameter]
    public bool HasMore { get; set; }

    /// <summary>CSS height value for the scrollable container (default 80vh).</summary>
    [Parameter]
    public string Height { get; set; } = "80vh";

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-61710d93e4ca4d538110d85f23fa3ab2/infiniteScroll.js");
        }

        // (Re)attach observer whenever HasMore is true and the sentinel is rendered.
        if (HasMore && _module is not null)
        {
            // Dispose any previous observer before creating a new one.
            if (_observer is not null)
            {
                await _observer.InvokeVoidAsync("disconnect");
                await _observer.DisposeAsync();
            }

            _observer = await _module.InvokeAsync<IJSObjectReference>(
                "createObserver", _sentinelRef, _dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnSentinelVisible()
    {
        if (_isLoading || !HasMore)
            return;

        _isLoading = true;
        StateHasChanged();

        await OnLoadMore.InvokeAsync();

        _isLoading = false;
        StateHasChanged();
    }

    public async ValueTask DisposeAsync()
    {
        if (_observer is not null)
        {
            await _observer.InvokeVoidAsync("disconnect");
            await _observer.DisposeAsync();
        }

        if (_module is not null)
            await _module.DisposeAsync();

        _dotNetRef?.Dispose();
    }
}

/**
 * Creates an IntersectionObserver that invokes a .NET callback
 * when the sentinel element scrolls into view.
 *
 * @param {Element} sentinel  - The DOM element to observe.
 * @param {object}  dotNetRef - A DotNetObjectReference for callbacks.
 * @returns {IntersectionObserver} The observer instance (exposes disconnect()).
 */
export function createObserver(sentinel, dotNetRef) {
    const observer = new IntersectionObserver(
        (entries) => {
            for (const entry of entries) {
                if (entry.isIntersecting) {
                    dotNetRef.invokeMethodAsync('OnSentinelVisible');
                }
            }
        },
        { rootMargin: '200px' }
    );

    observer.observe(sentinel);
    return observer;
}

